1	import { Currency } from "./money"
2	import type { Order } from "./order"
3	
4	export interface Refund {
5	    orderId: string
6	    amount: number
7	    currency: Currency
8	}
9	
10	const refunds: Refund[] = []
11	
12	export function issueRefund(orderId: string, amount: number, currency: Currency = "EUR"): Refund {
13	    const refund = { orderId, amount, currency }
14	    refunds.push(refund)
15	    return refund
16	}
17	
18	export function refundsOf(orderId: string): Refund[] {
19	    return refunds.filter((r) => r.orderId === orderId)
20	}
21	
22	/*  full refund of a paid order  */
23	export function refundOrder(order: Order): Refund {
24	    if (order.status !== "paid")
25	        throw new Error("only paid orders can be refunded")
26	    return issueRefund(order.id, order.subtotal, order.currency)
27	}
28

1	const stock    = new Map<string, number>()
2	const reserved = new Map<string, number>()
3	
4	export function setStock(sku: string, quantity: number): void {
5	    stock.set(sku, quantity)
6	}
7	
8	export function available(sku: string): number {
9	    return (stock.get(sku) ?? 0) - (reserved.get(sku) ?? 0)
10	}
11	
12	export function reserve(sku: string, quantity: number): boolean {
13	    if (available(sku) < quantity)
14	        return false
15	    reserved.set(sku, (reserved.get(sku) ?? 0) + quantity)
16	    return true
17	}
18	
19	export function release(sku: string, quantity: number): void {
20	    const current = reserved.get(sku) ?? 0
21	    reserved.set(sku, Math.max(0, current - quantity))
22	}
